args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?husband ?deathPlace ?deathPlaceLabel WHERE {
  dbr:Bess_Taffel dbo:spouse ?husband .
  ?husband dbo:deathPlace ?deathPlace .
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel . FILTER(lang(?deathPlaceLabel) = "en") }
} ORDER BY ?deathPlaceLabel

